-- Autostart
hl.on("hyprland.start", function()
    hl.exec_cmd("~/.config/hypr/scripts/xdg.sh")
    hl.exec_cmd("waybar -c ~/.config/waybar/themes/opium/config -s ~/.config/waybar/themes/opium/style.css")
    hl.exec_cmd("/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")
    hl.exec_cmd("swaync")
    hl.exec_cmd("~/.config/hypr/scripts/gtk.sh")
    hl.exec_cmd("hypridle")
    hl.exec_cmd("wl-paste --watch cliphist store")
    hl.exec_cmd("~/.config/ml4w/scripts/ml4w-autostart.sh")
    hl.exec_cmd("~/.config/hypr/scripts/cleanup.sh")
    hl.exec_cmd("~/.config/nwg-dock-hyprland/launch.sh")
    hl.exec_cmd("hyprpm reload")
    hl.exec_cmd("doomfire-wallpaper")
    hl.exec_cmd("flameshot")
    hl.exec_cmd("openrazer-daemon -Fv")
    hl.exec_cmd("hyprsunset")
    hl.exec_cmd("nerdshade -latitude 51.448 -longitude -2.53936 -loop")
    hl.exec_cmd("steam -silent")
    hl.exec_cmd("python3 ~/.config/ml4w/scripts/gamepad-monitor.py")
    hl.exec_cmd("ghostty")
    hl.exec_cmd("env LD_PRELOAD=/usr/lib/libgtk4-layer-shell.so python ~/Documents/overkeys-vibeclone/layer_overlay.py")
end)

-- Exec (run every reload)
hl.on("config.reloaded", function()
    hl.exec_cmd("~/.config/com.ml4w.hyprlandsettings/hyprctl.sh")
end)
